// Ensure all restaurants have direct properties
restaurants.forEach(r => {
  const t = restaurantI18n[r.id];
  if (t) {
    if (t.ko) {
      if (!r.nameKo) r.nameKo = t.ko.name;
      if (!r.genreKo) r.genreKo = t.ko.genre;
      if (!r.recommendedDishKo) r.recommendedDishKo = t.ko.recommendedDish;
      if (!r.descriptionKo) r.descriptionKo = t.ko.description;
      if (!r.areaNameKo) r.areaNameKo = t.ko.areaName;
      if (!r.dietaryNotesKo) r.dietaryNotesKo = t.ko.dietaryNotes;
      if (t.ko.note && r.payment && !r.payment.noteKo) r.payment.noteKo = t.ko.note;
    }
    if (t.zh) {
      if (!r.nameZh) r.nameZh = t.zh.name;
      if (!r.genreZh) r.genreZh = t.zh.genre;
      if (!r.recommendedDishZh) r.recommendedDishZh = t.zh.recommendedDish;
      if (!r.descriptionZh) r.descriptionZh = t.zh.description;
      if (!r.areaNameZh) r.areaNameZh = t.zh.areaName;
      if (!r.dietaryNotesZh) r.dietaryNotesZh = t.zh.dietaryNotes;
      if (t.zh.note && r.payment && !r.payment.noteZh) r.payment.noteZh = t.zh.note;
    }
  }
});

// Support both direct script tag (file:// protocol) and ES module environments
if (typeof window !== 'undefined') {
  window.UNIMAP_DATA = { i18n, restaurants, restaurantI18n };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { i18n, restaurants, restaurantI18n };
}
